mapper.sql:
WHERE A.PRD_STAT_CD IN ('30', '40', '50')

	AND A.L_CAT_CD = #{lCatCd}


	AND A.M_CAT_CD = #{mCatCd}


	AND A.S_CAT_CD = #{sCatCd}


	AND (A.PRD_NM LIKE CONCAT('%', #{searchKeyword}, '%')
	  OR A.SMPL_DESC LIKE CONCAT('%', #{searchKeyword}, '%'))

mapper.select:
/* PrdSQL.selectPrdList */ SELECT A.PRD_CD AS "prdCd", A.PRD_NM AS "prdNm", A.SMPL_DESC AS "smplDesc", A.PRD_STAT_CD AS "prdStatCd", B.SALE_PRC AS "salePrc", B.CARD_DISC_PRC AS "cardDiscPrc", B.CASH_DISC_PRC AS "cashDiscPrc", C.IMG_PATH AS "imgPath", D.CAT_NM AS "lCatNm" FROM TB_PRD_MST A LEFT JOIN TB_PRD_PRC B ON A.PRD_CD = B.PRD_CD LEFT JOIN TB_PRD_IMG C ON A.PRD_CD = C.PRD_CD AND C.IMG_TP_CD = '10' AND C.SORT_SEQ = 1 LEFT JOIN TB_CAT_MNG D ON A.L_CAT_CD = D.CAT_CD
ORDER BY B.CASH_DISC_PRC ASC, A.REG_DT DESC
ORDER BY B.CASH_DISC_PRC DESC, A.REG_DT DESC
ORDER BY A.PRD_NM ASC
ORDER BY A.REG_DT DESC
LIMIT #{pageSize} OFFSET #{limitStart}

/* PrdSQL.selectPrdListCnt */
SELECT COUNT(*)
FROM TB_PRD_MST A
